import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { Plus, Users, MapPin, Calendar, Circle, Activity, Target, Zap, Star } from 'lucide-react';

interface Game {
  id: string;
  title: string;
  sport: string;
  location: string;
  max_players: number;
  current_players: number;
  creator_name: string;
  created_at: string;
}

const sportIcons: { [key: string]: React.ComponentType<any> } = {
  basketball: Circle,
  soccer: Target,
  football: Activity,
  tennis: Zap,
  volleyball: Star,
};

const sportColors: { [key: string]: string } = {
  basketball: 'bg-orange-500',
  soccer: 'bg-green-500',
  football: 'bg-red-500',
  tennis: 'bg-yellow-500',
  volleyball: 'bg-purple-500',
};

const Dashboard: React.FC = () => {
  const [games, setGames] = useState<Game[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user } = useAuth();

  useEffect(() => {
    fetchGames();
  }, []);

  const fetchGames = async () => {
    try {
      const response = await fetch('http://localhost:5001/api/games');
      if (!response.ok) {
        throw new Error('Failed to fetch games');
      }
      const data = await response.json();
      setGames(data);
    } catch (error) {
      setError('Failed to load games');
    } finally {
      setLoading(false);
    }
  };

  const handleJoinGame = async (gameId: string) => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`http://localhost:5001/api/games/${gameId}/join`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to join game');
      }

      // Refresh games list
      fetchGames();
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Failed to join game');
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto">
      <div className="mb-8">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Welcome back, {user?.username}! 🏀</h1>
            <p className="mt-2 text-gray-600">Find and join pickup games in your area</p>
          </div>
          <Link
            to="/create-game"
            className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
          >
            <Plus className="w-4 h-4 mr-2" />
            Create Game
          </Link>
        </div>
      </div>

      {error && (
        <div className="mb-6 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md">
          {error}
        </div>
      )}

      {games.length === 0 ? (
        <div className="text-center py-12">
          <div className="mx-auto h-24 w-24 bg-gray-100 rounded-full flex items-center justify-center mb-4">
            <Circle className="h-12 w-12 text-gray-400" />
          </div>
          <h3 className="text-lg font-medium text-gray-900 mb-2">No games available</h3>
          <p className="text-gray-600 mb-6">Be the first to create a pickup game!</p>
          <Link
            to="/create-game"
            className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700"
          >
            <Plus className="w-4 h-4 mr-2" />
            Create First Game
          </Link>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {games.map((game) => {
            const SportIcon = sportIcons[game.sport.toLowerCase()] || Circle;
            const sportColor = sportColors[game.sport.toLowerCase()] || 'bg-gray-500';

            return (
              <div key={game.id} className="bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow duration-200">
                <div className="p-6">
                  <div className="flex items-center justify-between mb-4">
                    <div className={`w-10 h-10 ${sportColor} rounded-lg flex items-center justify-center`}>
                      <SportIcon className="w-6 h-6 text-white" />
                    </div>
                    <span className="text-sm font-medium text-gray-500 capitalize">{game.sport}</span>
                  </div>

                  <h3 className="text-lg font-semibold text-gray-900 mb-2">{game.title}</h3>

                  <div className="space-y-2 mb-4">
                    <div className="flex items-center text-sm text-gray-600">
                      <MapPin className="w-4 h-4 mr-2" />
                      {game.location}
                    </div>
                    <div className="flex items-center text-sm text-gray-600">
                      <Users className="w-4 h-4 mr-2" />
                      {game.current_players}/{game.max_players} players
                    </div>
                    <div className="flex items-center text-sm text-gray-600">
                      <Calendar className="w-4 h-4 mr-2" />
                      {formatDate(game.created_at)}
                    </div>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-500">by {game.creator_name}</span>
                    <button
                      onClick={() => handleJoinGame(game.id)}
                      disabled={game.current_players >= game.max_players}
                      className="inline-flex items-center px-3 py-1.5 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                    >
                      {game.current_players >= game.max_players ? 'Full' : 'Join'}
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default Dashboard;
